versions.variantCss:
.wemd-brand-sign[data-variant="bytedance-sign-inline"] {
  background: var(--wemd-bg-soft);
  border-radius: var(--wemd-border-radius);
  padding: 24px 28px;
  margin: 24px 0;
  border-left: 4px solid var(--wemd-primary);
}
.wemd-brand-sign[data-variant="bytedance-sign-inline"] .wemd-bs-wrapper {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
}
.wemd-brand-sign[data-variant="bytedance-sign-inline"] .wemd-bs-logo {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  background: linear-gradient(135deg, var(--wemd-primary), var(--wemd-primary-dark));
  color: #ffffff;
  font-size: 22px;
  font-weight: 700;
  border-radius: 10px;
  margin-right: 16px;
  flex-shrink: 0;
}
.wemd-brand-sign[data-variant="bytedance-sign-inline"] .wemd-bs-brand-name {
  color: var(--wemd-text-strong);
  font-size: 18px;
  font-weight: 700;
  margin-right: 12px;
}
.wemd-brand-sign[data-variant="bytedance-sign-inline"] .wemd-bs-slogan {
  color: var(--wemd-primary);
  font-size: 14px;
  font-weight: 500;
  margin-right: 12px;
}
.wemd-brand-sign[data-variant="bytedance-sign-inline"] .wemd-bs-subtext {
  color: var(--wemd-text-soft);
  font-size: 12px;
  margin: 0;
}
